function countMaxOrSubsets(nums) {
  let target = 0;
  for (const num of nums) {
    target |= num;
  }
  let count = 0;

  const backtrack = (index, current) => {
    if (index === nums.length) {
      if (current === target) {
        count++;
      }
      return;
    }
    backtrack(index + 1, current | nums[index]);
    backtrack(index + 1, current);
  };

  backtrack(0, 0);
  return count;
}

