function countMaxOrSubsets(nums) {
  // Enumerate every non-empty bitmask, track the best OR seen and how often it occurs.
  const n = nums.length;
  let best = -1, ways = 0;
  for (let mask = 1; mask < (1 << n); mask++) {
    let value = 0;
    for (let i = 0; i < n; i++) if (mask & (1 << i)) value |= nums[i];
    if (value > best) { best = value; ways = 1; }
    else if (value === best) ways++;
  }
  return ways;
}

