function generate(rand, size) {
  const n = size === 'large' ? 14 + Math.floor(rand() * 3) : 1 + Math.floor(rand() * 10);
  const style = rand();
  // Small values share bits often (many ties); single bits and big values make the maximum rare.
  const value = () => {
    if (style < 0.35) return 1 + Math.floor(rand() * 15);
    if (style < 0.6) return 1 << Math.floor(rand() * 17);
    return 1 + Math.floor(rand() * 100000);
  };
  return [Array.from({ length: n }, value)];
}
